import React, { useEffect, useState } from "react";
import { stats } from "../data/portfolioData";

const ROLES = [
  "Full Stack Developer",
  "React Engineer",
  "Node.js Developer",
  "TypeScript Enthusiast",
  "Open Source Contributor",
];

export default function Hero() {
  const [roleIdx, setRoleIdx] = useState(0);
  const [displayed, setDisplayed] = useState("");
  const [typing, setTyping] = useState(true);

  useEffect(() => {
    const role = ROLES[roleIdx];
    if (typing) {
      if (displayed.length < role.length) {
        const t = setTimeout(() => setDisplayed(role.slice(0, displayed.length + 1)), 60);
        return () => clearTimeout(t);
      } else {
        const t = setTimeout(() => setTyping(false), 1800);
        return () => clearTimeout(t);
      }
    } else {
      if (displayed.length > 0) {
        const t = setTimeout(() => setDisplayed(displayed.slice(0, -1)), 35);
        return () => clearTimeout(t);
      } else {
        setRoleIdx((i) => (i + 1) % ROLES.length);
        setTyping(true);
      }
    }
  }, [displayed, typing, roleIdx]);

  return (
    <section
      id="hero"
      className="relative min-h-screen flex flex-col items-center justify-center px-6 pt-24 pb-16 overflow-hidden"
    >
      {/* Background layers */}
      <div className="absolute inset-0 bg-bg-primary" />

      {/* Grid */}
      <div
        className="absolute inset-0 opacity-30"
        style={{
          backgroundImage:
            "linear-gradient(rgba(96,165,250,0.08) 1px, transparent 1px), linear-gradient(90deg, rgba(96,165,250,0.08) 1px, transparent 1px)",
          backgroundSize: "56px 56px",
        }}
      />

      {/* Radial glows */}
      <div className="absolute top-1/4 left-1/2 -translate-x-1/2 w-[700px] h-[400px] rounded-full bg-accent-blue/5 blur-3xl animate-glow-pulse pointer-events-none" />
      <div className="absolute bottom-1/4 left-1/3 w-[400px] h-[300px] rounded-full bg-accent-purple/5 blur-3xl animate-glow-pulse pointer-events-none" style={{ animationDelay: "1.5s" }} />
      <div className="absolute top-1/3 right-1/4 w-[300px] h-[300px] rounded-full bg-accent-cyan/5 blur-3xl animate-glow-pulse pointer-events-none" style={{ animationDelay: "3s" }} />

      {/* Floating code snippets */}
      <div className="absolute top-32 right-8 lg:right-24 hidden lg:block animate-float opacity-20 select-none" style={{ animationDelay: "0s" }}>
        <div className="font-mono text-xs text-accent-blue bg-bg-card border border-white/5 rounded-lg p-3 leading-relaxed">
          <span className="text-accent-purple">const</span> <span className="text-accent-cyan">stack</span> = [<br />
          &nbsp;&nbsp;<span className="text-green-400">"React"</span>,<br />
          &nbsp;&nbsp;<span className="text-green-400">"Node.js"</span>,<br />
          &nbsp;&nbsp;<span className="text-green-400">"Postgres"</span><br />
          ];
        </div>
      </div>
      <div className="absolute bottom-40 left-8 lg:left-24 hidden lg:block animate-float opacity-20 select-none" style={{ animationDelay: "2s" }}>
        <div className="font-mono text-xs text-accent-cyan bg-bg-card border border-white/5 rounded-lg p-3 leading-relaxed">
          <span className="text-accent-purple">async function</span> <span className="text-accent-blue">deploy</span>() {"{"}<br />
          &nbsp;&nbsp;<span className="text-accent-purple">await</span> ship();<br />
          &nbsp;&nbsp;<span className="text-slate-500">// 🚀 done</span><br />
          {"}"}
        </div>
      </div>

      {/* Main content */}
      <div className="relative z-10 max-w-4xl mx-auto text-center">
        {/* Eyebrow */}
        <div className="inline-flex items-center gap-3 mb-8 px-4 py-2 rounded-full border border-accent-blue/20 bg-accent-blue/5">
          <span className="w-2 h-2 rounded-full bg-accent-green animate-pulse" />
          <span className="font-mono text-xs text-slate-400 tracking-widest uppercase">
            Available for hire
          </span>
        </div>

        {/* Name */}
        <h1 className="font-mono font-bold leading-tight mb-6" style={{ fontSize: "clamp(2.8rem, 7vw, 5rem)" }}>
          <span className="text-white">Hi, I'm </span>
          <span className="text-gradient">Milinda Nirwan</span>
          <br />
          <span className="text-white">I build </span>
          <span className="text-accent-blue">full-stack</span>
          <br />
          <span className="text-white">products.</span>
        </h1>

        {/* Typewriter role */}
        <div className="font-mono text-lg text-slate-400 mb-6 h-8 flex items-center justify-center gap-1">
          <span className="text-accent-cyan">&gt;</span>
          <span className="text-slate-300">{displayed}</span>
          <span className="inline-block w-0.5 h-5 bg-accent-blue animate-blink" />
        </div>

        {/* Description */}
        <p className="text-slate-400 text-lg max-w-2xl mx-auto mb-10 leading-relaxed">
          I craft <span className="text-white font-medium">end-to-end web applications</span> — from database schemas to pixel-perfect UIs. I care deeply about{" "}
          <span className="text-white font-medium">performance, developer experience,</span> and{" "}
          <span className="text-white font-medium">shipping things that scale.</span>
        </p>

        {/* CTAs */}
        <div className="flex flex-wrap items-center justify-center gap-4 mb-16">
          <button
            onClick={() => document.querySelector("#projects").scrollIntoView({ behavior: "smooth" })}
            className="group inline-flex items-center gap-3 px-7 py-3.5 rounded-xl bg-accent-blue text-bg-primary font-mono font-bold text-sm transition-all hover:scale-105 hover:shadow-lg hover:shadow-accent-blue/25"
          >
            View my work
            <svg className="w-4 h-4 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 8l4 4m0 0l-4 4m4-4H3" />
            </svg>
          </button>
          <a
            href="/resume.pdf"
            className="inline-flex items-center gap-3 px-7 py-3.5 rounded-xl border border-white/10 text-slate-300 font-mono text-sm hover:border-accent-blue/40 hover:text-white hover:bg-accent-blue/5 transition-all"
          >
            Download CV
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
          </a>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 max-w-2xl mx-auto">
          {stats.map((s) => (
            <div
              key={s.label}
              className="bg-bg-card border border-white/5 rounded-xl p-4 hover:border-accent-blue/20 transition-all"
            >
              <div className="font-mono font-bold text-2xl text-gradient mb-1">{s.value}</div>
              <div className="text-slate-500 text-xs">{s.label}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Scroll indicator */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-slate-600">
        <span className="font-mono text-xs tracking-widest uppercase">Scroll</span>
        <div className="w-px h-12 bg-gradient-to-b from-slate-600 to-transparent" />
      </div>
    </section>
  );
}
